 "content": "def transform(grid):
    h,w=len(grid),len(grid[0]); seen=set(); comps=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c]!=3 or (r,c) in seen: continue
            stack=[(r,c)]; seen.add((r,c)); cells=[]
            while stack:
                x,y=stack.pop(); cells.append((x,y))
                for nx,ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0<=nx<h and 0<=ny<w and grid[nx][ny]==3 and (nx,ny) not in seen:
                        seen.add((nx,ny)); stack.append((nx,ny))
            comps.append(cells)
    # Remove the patterned object with the fewest embedded 9 markers.
    target=min(comps,key=lambda cells:sum(grid[r][c]==9 for r,c in cells))
    out=[row[:] for row in grid]
    for r,c in target: out[r][c]=0
    for r,c in target:
        for nr,nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if 0<=nr<h and 0<=nc<w and grid[nr][nc]==9: out[nr][nc]=0
    return out
